BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path = public, extensions;
SELECT no_plan();
SELECT ok(NOT has_table_privilege('authenticated','public.paddle_checkout_authorizations','SELECT'), 'authenticated cannot SELECT checkout ledger');
SELECT ok(NOT has_table_privilege('authenticated','public.paddle_checkout_authorizations','INSERT'), 'authenticated cannot INSERT checkout ledger');
SELECT ok(NOT has_table_privilege('authenticated','public.paddle_checkout_authorizations','UPDATE'), 'authenticated cannot UPDATE checkout ledger');
SELECT ok(NOT has_table_privilege('authenticated','public.paddle_checkout_authorizations','DELETE'), 'authenticated cannot DELETE checkout ledger');
SELECT ok(NOT has_table_privilege('anon','public.paddle_checkout_authorizations','SELECT'), 'anonymous cannot SELECT checkout ledger');
SELECT ok(NOT has_table_privilege('anon','public.paddle_checkout_authorizations','INSERT'), 'anonymous cannot INSERT checkout ledger');
SELECT ok(NOT has_table_privilege('anon','public.paddle_checkout_authorizations','UPDATE'), 'anonymous cannot UPDATE checkout ledger');
SELECT ok(NOT has_table_privilege('anon','public.paddle_checkout_authorizations','DELETE'), 'anonymous cannot DELETE checkout ledger');
SELECT ok(NOT has_function_privilege('anon','public.reserve_paddle_checkout(uuid,uuid,text,text,timestamptz)','EXECUTE'), 'anonymous cannot reserve checkout');
INSERT INTO auth.users(id,email) VALUES('96969696-0000-4000-8000-000000000001','checkout-binding@example.test');
SELECT is(public.reserve_paddle_checkout('96969696-0000-4000-8000-000000000001','96969696-0000-4000-8000-000000000002','pri_plan','sandbox',now()+interval '30 minutes')->>'action','create','first caller reserves creation');
SELECT is(public.reserve_paddle_checkout('96969696-0000-4000-8000-000000000001','96969696-0000-4000-8000-000000000003','pri_plan','sandbox',now()+interval '30 minutes')->>'action','busy','another caller cannot create a second transaction');
SELECT ok(public.record_paddle_checkout_transaction('96969696-0000-4000-8000-000000000001','96969696-0000-4000-8000-000000000002','txn_owned'),'transaction ID is durable before configuration');
SELECT is(public.reserve_paddle_checkout('96969696-0000-4000-8000-000000000001','96969696-0000-4000-8000-000000000003','pri_plan','sandbox',now()+interval '30 minutes')->>'action','configure','failed configuration can resume same transaction');
SELECT ok(public.finish_paddle_checkout('96969696-0000-4000-8000-000000000001','96969696-0000-4000-8000-000000000002','txn_owned'),'configured transaction is available');
SELECT is(public.reserve_paddle_checkout('96969696-0000-4000-8000-000000000001','96969696-0000-4000-8000-000000000003','pri_plan','sandbox',now()+interval '30 minutes')->>'action','reuse','retained authorization reuses same transaction');
SELECT is(public.reserve_paddle_checkout('96969696-0000-4000-8000-000000000001','96969696-0000-4000-8000-000000000003','pri_other','sandbox',now()+interval '30 minutes')->>'action','close','different plan requires cancellation first');
SELECT is(public.reserve_paddle_checkout('96969696-0000-4000-8000-000000000001','96969696-0000-4000-8000-000000000003','pri_other','sandbox',now()+interval '30 minutes')->>'action','close','remote cancellation failure can retry same closing transaction');
SELECT ok(NOT public.bind_paddle_checkout('96969696-0000-4000-8000-000000000001','96969696-0000-4000-8000-000000000002','txn_owned','sub_owned','ctm_owned','pri_other','sandbox',now()),'wrong price cannot consume authorization');
SELECT ok(public.bind_paddle_checkout('96969696-0000-4000-8000-000000000001','96969696-0000-4000-8000-000000000002','txn_owned','sub_owned','ctm_owned','pri_plan','sandbox',now()),'paid transaction can bind during closing inspection');
SELECT ok(public.bind_paddle_checkout('96969696-0000-4000-8000-000000000001','96969696-0000-4000-8000-000000000002','txn_owned','sub_owned','ctm_owned','pri_plan','sandbox',now()+interval '1 day'),'same subscription remains bound after expiry');
SELECT ok(NOT public.bind_paddle_checkout('96969696-0000-4000-8000-000000000001','96969696-0000-4000-8000-000000000002','txn_owned','sub_replay','ctm_owned','pri_plan','sandbox',now()),'a second subscription cannot consume the transaction binding');
SELECT is(public.reserve_paddle_checkout('96969696-0000-4000-8000-000000000001','96969696-0000-4000-8000-000000000003','pri_other','sandbox',now()+interval '30 minutes')->>'action','blocked','bound purchase blocks issuance before webhook mirror catches up');
SELECT ok(public.mark_paddle_subscription_terminal('96969696-0000-4000-8000-000000000001','sub_owned'),'terminal subscription closes durable obligation');
SELECT is(public.reserve_paddle_checkout('96969696-0000-4000-8000-000000000001','96969696-0000-4000-8000-000000000003','pri_other','sandbox',now()+interval '30 minutes')->>'action','create','terminal old purchase allows a new checkout');
SELECT ok(public.finish_paddle_checkout('96969696-0000-4000-8000-000000000001','96969696-0000-4000-8000-000000000003',NULL,true),'definitive remote rejection releases no-ID creation');
SELECT is(public.reserve_paddle_checkout('96969696-0000-4000-8000-000000000001','96969696-0000-4000-8000-000000000004','pri_other','sandbox',now()+interval '30 minutes')->>'action','create','healthy retry can reserve after definitive rejection');
SELECT * FROM finish();
ROLLBACK;
